// Fetch today's briefing from saralprivacy.com
// Set BRIEFING_CRON_SECRET in n8n Settings → Environment Variables
const secret = $env.BRIEFING_CRON_SECRET || '';

const response = await fetch('https://saralprivacy.com/api/briefings/today', {
  headers: {
    'Authorization': 'Bearer ' + secret
  }
});

if (response.status === 404) {
  // No briefing today — return skip signal
  return [{ json: { skip: true, reason: 'No briefing published today' } }];
}

if (!response.ok) {
  throw new Error('Failed to fetch briefing: ' + response.status + ' ' + response.statusText);
}

const briefing = await response.json();
return [{ json: { ...briefing, skip: false } }];

// Keep only subscribed users — skip unsubscribed / bounced
const items = $input.all();
const briefing = $('Fetch Today Briefing').first().json;

return items
  .filter(item => {
    const status = (item.json.Status || item.json.status || 'active').toLowerCase();
    return status !== 'unsubscribed' && status !== 'bounced' && status !== 'inactive';
  })
  .map(item => ({
    json: {
      email:        item.json.Email || item.json.email || '',
      name:         item.json.Name  || item.json.name  || 'Reader',
      // Attach briefing data to each subscriber row
      title:        briefing.title        || '',
      url:          briefing.url          || '',
      hook_line1:   briefing.hook_line1   || '',
      hook_line2:   briefing.hook_line2   || '',
      card_what:    briefing.card_what    || '',
      card_why:     briefing.card_why     || '',
      card_action:  briefing.card_action  || '',
      save_line:    briefing.save_line    || '',
      excerpt:      briefing.excerpt      || '',
      read_time:    briefing.read_time    || 3,
      category:     briefing.category     || '',
      date:         briefing.date         || ''
    }
  }));

